// Lab 21.1: the sizes and entry points shared by the driver, your kernels and the provided
// baseline. Provided; you do not edit this file.
//
// The problem (book section 21.2, pp. 515-517): a regular 3D grid of nz x ny x nx points
// with the same spacing in every direction, so point (i, j, k) sits at
// (i * gridspacing, j * gridspacing, k * gridspacing). Each atom is four floats: x, y, z
// and its charge. The potential at a point is the sum, over all atoms, of
// charge / distance (Fig. 21.2).
//
// Every launch below ADDS the potential of `numatoms` atoms to each point of ONE slice, k,
// and leaves every other slice alone. It feeds the atoms to the kernel `chunk` at a time
// (the host loop of p. 517): copy at most `chunk` atoms, launch, repeat.
//
// Layout (the project's conventions): the grid is row-major float, x fastest:
//   energygrid[(k * ny + j) * nx + i]     the book writes grid.x*grid.y*k + grid.x*j + i
#pragma once

// Atoms per chunk, at most: 1,024 atoms x 4 floats x 4 bytes = 16 KB of constant memory.
// Your kernel.cu and the provided coarse_adjacent.cu each declare one such array, 32 KB in
// all, under the 64 KB NVIDIA documents for every current GPU (notes/today/ch05-facts.md A4).
#define CHUNK_MAX 1024

// Gather and coarsened kernels: 2D blocks of BLOCK_X x BLOCK_Y threads (256).
// Scatter kernel: 1D blocks of BLOCK_X threads.
// 64 is a whole number of warps on NVIDIA (32) and of wavefronts on AMD (64 or 32).
#define BLOCK_X 64
#define BLOCK_Y 4

// Grid points per thread in the coarsened kernels (the book's COARSEN_FACTOR, p. 520).
#define COARSEN 4

#if defined(__OBJC__)
// ------------------------------------------------------------------- Metal (launch.mm)
// `atoms` is ONE buffer of numatoms float4s (x, y, z, charge), 16 bytes per atom. Each
// function encodes its whole chunk loop into the open encoder it is given and commits
// nothing. The arguments mean what they mean in the CUDA launches below.
#import <Metal/Metal.h>

void encodeDcsScatter(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                      id<MTLBuffer> energygrid, int nx, int ny, int nz, float gridspacing, int k,
                      id<MTLBuffer> atoms, int numatoms, int chunk);
void encodeDcsGather(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                     id<MTLBuffer> energygrid, int nx, int ny, int nz, float gridspacing, int k,
                     id<MTLBuffer> atoms, int numatoms, int chunk);
void encodeDcsCoarsened(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                        id<MTLBuffer> energygrid, int nx, int ny, int nz, float gridspacing, int k,
                        id<MTLBuffer> atoms, int numatoms, int chunk);
// Provided (../shared/coarse_adjacent_launch.mm): the corrected Fig. 21.8.
void encodeDcsCoarseAdjacent(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                             id<MTLBuffer> energygrid, int nx, int ny, int nz, float gridspacing, int k,
                             id<MTLBuffer> atoms, int numatoms, int chunk);

#else
// ------------------------------------------------------- CUDA, HIP and the emulators
// energygrid  DEVICE pointer to nz * ny * nx floats
// atoms       HOST pointer to numatoms * 4 floats (x, y, z, charge)
// k           the slice, 0 <= k < nz
// chunk       atoms per launch, 1 <= chunk <= CHUNK_MAX
// The launches return without waiting for the device.

// Yours (kernel.cu): Fig. 21.5, Fig. 21.6 and Fig. 21.10.
void launchDcsScatter(float* energygrid, int nx, int ny, int nz, float gridspacing, int k,
                      const float* atoms, int numatoms, int chunk);
void launchDcsGather(float* energygrid, int nx, int ny, int nz, float gridspacing, int k,
                     const float* atoms, int numatoms, int chunk);
void launchDcsCoarsened(float* energygrid, int nx, int ny, int nz, float gridspacing, int k,
                        const float* atoms, int numatoms, int chunk);
// Provided (../shared/coarse_adjacent.cu): the corrected Fig. 21.8.
void launchDcsCoarseAdjacent(float* energygrid, int nx, int ny, int nz, float gridspacing, int k,
                             const float* atoms, int numatoms, int chunk);
#endif
